async function piAirbnbPageLooksLoggedIn(page) {
  const url = page.url();
  if (/log.?in|sign.?in/i.test(url)) return false;
  const text = await page.locator('body').innerText().catch(function () { return ''; });
  if (/log in to continue/i.test(text) && /log.?in/i.test(url)) return false;
  if (/hosting|reservations|calendar/i.test(url + ' ' + text)) return true;
  return !/log.?in|sign.?in/i.test(url);
}

